-- OurMynd: separate, evidenced consent for sending messages to a third-party AI.
--
-- Run: psql "$DATABASE_URL" -f supabase/migrations/20261122000000_ai_consent.sql
--   or: npm run migrate
--
-- The coach's replies are generated by a third-party AI provider (Groq), which
-- means what the user types is sent off the account to a company that is not
-- us. App Store Review Guideline 5.1.2(i) requires that this is disclosed, that
-- the recipient is named, and that the user agrees before any of it is sent -
-- not after, and not as a line buried in the Terms.
--
-- This is a DIFFERENT consent from health_consent and is stored separately on
-- purpose. Health consent is optional enrichment: decline it and the coach
-- still runs, just without your mood and memory in the prompt. AI consent is
-- the floor: the coach cannot function at all without sending your words to the
-- provider, so declining it means the coach is unavailable (and nothing else
-- is). Folding the two into one answer would have made "no third-party AI" and
-- "no health context" the same button, which they are not.
--
-- Shape mirrors health_consent for the same four reasons documented there: own
-- screen, not a condition of the account, withdrawable, evidenced. An
-- append-only log is the source of truth; the columns on users are a cache of
-- its latest row so gating a coaching turn costs no join.

-- ============ CURRENT STATE (the gate) ============
-- Three-valued: null = never asked, false = declined, true = agreed. The
-- distinction between "said no" and "not asked yet" is what stops the app
-- nagging someone who has already declined.
alter table users add column if not exists ai_consent_granted boolean;

-- When they last answered, whichever way. Drives the Settings line and the
-- audit view.
alter table users add column if not exists ai_consent_decided_at timestamptz;

-- The disclosure version on screen when they answered. When the disclosure
-- changes materially (a new provider, a new category of data sent) this is what
-- marks whose agreement is now stale and has to be asked again.
alter table users add column if not exists ai_consent_version text;

-- ============ THE EVIDENCE (append-only) ============
create table if not exists ai_consent_events (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references users(id) on delete cascade,
  -- true = agreed, false = withdrawn/declined.
  granted         boolean not null,
  disclosure_version text not null,
  -- Where the decision was taken: 'coach' (the in-context gate) or 'settings'.
  source          text not null,
  occurred_at     timestamptz not null default now()
);

-- The audit read is always "this user's decisions, newest first".
create index if not exists ai_consent_events_user_idx
  on ai_consent_events (user_id, occurred_at desc);

-- No update/delete path in the app: rows go only when the account does, by the
-- cascade above. An audit trail the audited party can edit is not one.

-- ============ ROW LEVEL SECURITY ============
-- Same treatment as health_consent_events, which this table is the sibling of.
-- Without it this would be the one consent table in the schema that any
-- connection pointed at this database could read in full.
--
-- Order matters. The hardening migration uses `force row level security`, not
-- just `enable`, because enable alone exempts the table owner - which is the
-- role the API connects as, so the policies would be decorative. The flip side
-- is that forcing it before the server has a policy of its own locks the
-- server out of its own table. So: policies first, switch on last.

-- The API server's own access. The role is read from the policy that already
-- exists on health_consent_events rather than assumed, because `current_user`
-- is not the same thing when this runs through the Supabase SQL editor as it
-- is when it runs through `npm run migrate`, and guessing wrong here is what
-- locks the server out.
do $$
declare api_role text;
begin
  select roles[1] into api_role
    from pg_policies
   where tablename = 'health_consent_events'
     and policyname = 'api_server_full_access';

  if api_role is null then
    raise exception 'no api_server_full_access policy on health_consent_events; refusing to force RLS and lock the API out';
  end if;

  execute 'drop policy if exists api_server_full_access on ai_consent_events';
  execute format('create policy api_server_full_access on ai_consent_events to %I using (true) with check (true)', api_role);
end $$;

-- Owner-only for any other role: a Supabase anon/authenticated client, a BI
-- tool. Reads auth.uid() where Supabase provides it, and is skipped where it
-- does not exist rather than creating a policy that references a missing
-- function.
do $$
begin
  if exists (select 1 from pg_proc where proname = 'uid'
              and pronamespace = (select oid from pg_namespace where nspname = 'auth')) then
    drop policy if exists own_rows on ai_consent_events;
    create policy own_rows on ai_consent_events
      using (user_id = auth.uid()) with check (user_id = auth.uid());
  end if;
end $$;

alter table ai_consent_events enable row level security;
alter table ai_consent_events force  row level security;
